-- Mantener Menú (punto 5 de la tanda de cierre): la tabla `menu` pasa a ser la fuente del menú lateral, del buscador general y de la matriz de
-- Roles y Permisos. Idempotente y en una transacción; se aplica como postgres con PGCLIENTENCODING=UTF8, DESPUÉS de un backup y de schema_seguridad_base.sql.
-- Qué hace:
--   1. Columnas nuevas: `visible_en_menu` (false = pantalla contextual: sin sidebar ni buscador), `solo_admin` (ventana exclusiva del Administrador) y
--      `protegida` (Mantener Menú, Usuarios, Roles y Permisos y su módulo: no se anulan, mueven ni dejan de ser exclusivas del Administrador).
--   2. Estructura: un MÓDULO es una fila sin padre y sin clave; una VENTANA es una fila con padre (su módulo) y con clave. CHECK `ck_menu_tipo`.
--   3. Siembra los 7 módulos y las 55 ventanas del sistema (ruta = endpoint de Flask) UNA sola vez: las filas que ya tienen ruta
--      (ya migradas, o editadas desde Mantener Menú) no se tocan al volver a correrlo. Resuelve `usuario` y `auditoria` (no tenían fila) y agrega `permiso` y `menu`.
--   4. Trigger `trg_menu_protegida`: la base impide borrar o debilitar una fila protegida aunque lo intente la aplicación.
BEGIN;

ALTER TABLE menu ADD COLUMN IF NOT EXISTS visible_en_menu BOOLEAN NOT NULL DEFAULT true;
ALTER TABLE menu ADD COLUMN IF NOT EXISTS solo_admin BOOLEAN NOT NULL DEFAULT false;
ALTER TABLE menu ADD COLUMN IF NOT EXISTS protegida BOOLEAN NOT NULL DEFAULT false;

DROP TRIGGER IF EXISTS trg_menu_protegida ON menu;

-- módulos
INSERT INTO menu (id_menu_padre, clave, descripcion, ruta, icono, orden)
SELECT NULL, NULL, v.nombre, NULL, v.icono, v.orden
  FROM (VALUES ('Agendamiento', 'fa-calendar-check', 1), ('Referenciales Agendamiento', 'fa-file-alt', 2), ('Referenciales Consultorio', 'fa-file-alt', 3), ('Módulo Consultorio', 'fa-file-medical', 4), ('Referenciales Facturación', 'fa-file-invoice-dollar', 5), ('Módulo Facturación', 'fa-cash-register', 6), ('Módulo Seguridad', 'fa-user-shield', 7)) AS v(nombre, icono, orden)
 WHERE NOT EXISTS (SELECT 1 FROM menu x WHERE x.id_menu_padre IS NULL AND x.clave IS NULL AND UPPER(x.descripcion) = UPPER(v.nombre));

-- ventanas que ya existían como filas sueltas (clave sin padre, sin ruta): se completan y se cuelgan de su módulo
UPDATE menu m
   SET id_menu_padre = p.id_menu, descripcion = v.etiqueta, ruta = v.ruta, icono = v.icono, orden = v.orden, visible_en_menu = v.visible, solo_admin = v.solo_admin
  FROM (VALUES ('Agendamiento', 'agenda', 'Registrar Agenda', 'agenda_bp.index', 'fa-calendar-alt', 10, true, false), ('Agendamiento', 'cita', 'Registrar Citas', 'cita.citaIndex', 'fa-book', 20, true, false), ('Agendamiento', 'avisos', 'Registrar Avisos', 'avisos_bp.avisos_recordatorios', 'fa-bell', 30, true, false), ('Agendamiento', 'paciente', 'Registrar Pacientes', 'paciente.pacienteIndex', 'fa-user-injured', 40, true, false), ('Agendamiento', 'funcionario', 'Registrar Funcionario', 'funcionario.funcionarioIndex', 'fa-users', 50, true, false), ('Agendamiento', 'medico', 'Registrar Médicos', 'medico.medicoIndex', 'fa-stethoscope', 60, true, false), ('Referenciales Agendamiento', 'ciudad', 'Ciudad', 'ciudad.ciudadIndex', 'fa-map-marker-alt', 10, true, false), ('Referenciales Agendamiento', 'cargo', 'Cargo', 'cargo.cargoIndex', 'fa-briefcase', 20, true, false), ('Referenciales Agendamiento', 'consultorio', 'Consultorio', 'consultorio.consultorioIndex', 'fa-clinic-medical', 30, true, false), ('Referenciales Agendamiento', 'disponibilidad', 'Disponibilidad Horaria', 'disponibilidad.disponibilidadIndex', 'fa-clock', 40, true, false), ('Referenciales Agendamiento', 'especialidad', 'Especialidad', 'especialidad.especialidadIndex', 'fa-certificate', 50, true, false), ('Referenciales Agendamiento', 'dia', 'Día', 'dia.diaIndex', 'fa-sun', 60, true, false), ('Referenciales Agendamiento', 'turno', 'Turno', 'turno.turnoIndex', 'fa-hourglass', 70, true, false), ('Referenciales Consultorio', 'tipodiagnostico', 'Tipo diagnóstico', 'tipodiagnostico.tipoDiagnosticoIndex', 'fa-microscope', 10, true, false), ('Referenciales Consultorio', 'sintoma', 'Síntomas', 'sintoma.sintomaIndex', 'fa-heartbeat', 20, true, false), ('Referenciales Consultorio', 'tipotratamiento', 'Tipo Tratamiento', 'tipotratamiento.tipoTratamientoIndex', 'fa-notes-medical', 30, true, false), ('Referenciales Consultorio', 'tipoinsumo', 'Tipo Insumo Utilizado', 'tipoinsumo.tipoInsumoIndex', 'fa-box-open', 40, true, false), ('Referenciales Consultorio', 'tipoprocedimientomedico', 'Tipo Procedimiento Médico', 'tipoprocedimientomedico.tipoProcedimientoMedicoIndex', 'fa-syringe', 50, true, false), ('Referenciales Consultorio', 'medicamento', 'Medicamentos', 'medicamento.medicamentoIndex', 'fa-pills', 60, true, false), ('Referenciales Consultorio', 'tipoestudio', 'Tipo Estudio', 'tipoestudio.tipoEstudioIndex', 'fa-x-ray', 70, true, false), ('Referenciales Consultorio', 'tipoanalisis', 'Tipo Análisis', 'tipoanalisis.tipoAnalisisIndex', 'fa-vial', 80, true, false), ('Módulo Consultorio', 'consulta', 'Registrar Consulta', 'consulta.consultaIndex', 'fa-stethoscope', 10, true, false), ('Módulo Consultorio', 'fichamedica', 'Gestión Fichas Médicas', 'fichamedica.fichaMedicaIndex', 'fa-file-medical-alt', 20, true, false), ('Módulo Consultorio', 'diagnostico', 'Gestión Diagnósticos', 'diagnostico_medico.diagnosticoIndex', 'fa-diagnoses', 30, true, false), ('Módulo Consultorio', 'historial', 'Historial Médico', 'historial.historialIndex', 'fa-history', 40, true, false), ('Módulo Consultorio', 'odontograma', 'Registrar Odontograma', 'odontograma.odontogramaIndex', 'fa-teeth', 50, true, false), ('Módulo Consultorio', 'tratamiento', 'Gestionar Tratamientos', 'tratamiento.tratamientoIndex', 'fa-prescription-bottle-alt', 60, true, false), ('Módulo Consultorio', 'receta', 'Generar Recetas e Indicaciones', 'receta.recetaIndex', 'fa-prescription', 70, true, false), ('Módulo Consultorio', 'sesiontratamiento', 'Procedimientos e Insumos (Sesiones)', 'sesiontratamiento.sesionTratamientoIndex', 'fa-notes-medical', 80, false, false), ('Módulo Consultorio', 'ordenestudio', 'Generar Orden de Estudios', 'ordenestudio.ordenEstudioIndex', 'fa-vial', 90, true, false), ('Módulo Consultorio', 'ordenanalisis', 'Generar Orden de Análisis', 'ordenanalisis.ordenAnalisisIndex', 'fa-flask', 100, true, false), ('Módulo Consultorio', 'justificativomedico', 'Generar Justificativo Médico', 'justificativomedico.justificativ