'fa-file-invoice', 60, true, false), ('Módulo Facturación', 'arqueo', 'Arqueo de Caja', 'arqueo.arqueoIndex', 'fa-calculator', 70, true, false), ('Módulo Seguridad', 'usuario', 'Gestión de Usuarios', 'usuario.usuarioIndex', 'fa-users-cog', 10, true, true), ('Módulo Seguridad', 'permiso', 'Roles y Permisos', 'permiso.permisoIndex', 'fa-key', 20, true, true), ('Módulo Seguridad', 'menu', 'Mantener Menú', 'menu.menuIndex', 'fa-bars', 30, true, true), ('Módulo Seguridad', 'auditoria', 'Tablero de Administrador', 'auditoria.auditoriaIndex', 'fa-shield-alt', 40, true, true), ('Módulo Seguridad', 'auditoriacambios', 'Auditoría de Cambios', 'auditoriacambios.auditoriaCambiosIndex', 'fa-history', 50, true, true), ('Módulo Seguridad', 'backup', 'Copias de Seguridad', 'backup.backupIndex', 'fa-database', 60, true, true)) AS v(modulo, clave, etiqueta, ruta, icono, orden, visible, solo_admin)
  JOIN menu p ON p.id_menu_padre IS NULL AND p.clave IS NULL AND UPPER(p.descripcion) = UPPER(v.modulo) AND p.activo
 WHERE m.clave = v.clave AND m.activo AND m.ruta IS NULL;

-- ventanas que no tenían fila (usuario, auditoria, permiso, menu)
INSERT INTO menu (id_menu_padre, clave, descripcion, ruta, icono, orden, visible_en_menu, solo_admin)
SELECT p.id_menu, v.clave, v.etiqueta, v.ruta, v.icono, v.orden, v.visible, v.solo_admin
  FROM (VALUES ('Agendamiento', 'agenda', 'Registrar Agenda', 'agenda_bp.index', 'fa-calendar-alt', 10, true, false), ('Agendamiento', 'cita', 'Registrar Citas', 'cita.citaIndex', 'fa-book', 20, true, false), ('Agendamiento', 'avisos', 'Registrar Avisos', 'avisos_bp.avisos_recordatorios', 'fa-bell', 30, true, false), ('Agendamiento', 'paciente', 'Registrar Pacientes', 'paciente.pacienteIndex', 'fa-user-injured', 40, true, false), ('Agendamiento', 'funcionario', 'Registrar Funcionario', 'funcionario.funcionarioIndex', 'fa-users', 50, true, false), ('Agendamiento', 'medico', 'Registrar Médicos', 'medico.medicoIndex', 'fa-stethoscope', 60, true, false), ('Referenciales Agendamiento', 'ciudad', 'Ciudad', 'ciudad.ciudadIndex', 'fa-map-marker-alt', 10, true, false), ('Referenciales Agendamiento', 'cargo', 'Cargo', 'cargo.cargoIndex', 'fa-briefcase', 20, true, false), ('Referenciales Agendamiento', 'consultorio', 'Consultorio', 'consultorio.consultorioIndex', 'fa-clinic-medical', 30, true, false), ('Referenciales Agendamiento', 'disponibilidad', 'Disponibilidad Horaria', 'disponibilidad.disponibilidadIndex', 'fa-clock', 40, true, false), ('Referenciales Agendamiento', 'especialidad', 'Especialidad', 'especialidad.especialidadIndex', 'fa-certificate', 50, true, false), ('Referenciales Agendamiento', 'dia', 'Día', 'dia.diaIndex', 'fa-sun', 60, true, false), ('Referenciales Agendamiento', 'turno', 'Turno', 'turno.turnoIndex', 'fa-hourglass', 70, true, false), ('Referenciales Consultorio', 'tipodiagnostico', 'Tipo diagnóstico', 'tipodiagnostico.tipoDiagnosticoIndex', 'fa-microscope', 10, true, false), ('Referenciales Consultorio', 'sintoma', 'Síntomas', 'sintoma.sintomaIndex', 'fa-heartbeat', 20, true, false), ('Referenciales Consultorio', 'tipotratamiento', 'Tipo Tratamiento', 'tipotratamiento.tipoTratamientoIndex', 'fa-notes-medical', 30, true, false), ('Referenciales Consultorio', 'tipoinsumo', 'Tipo Insumo Utilizado', 'tipoinsumo.tipoInsumoIndex', 'fa-box-open', 40, true, 