  JOIN menu p ON p.id_menu_padre IS NULL AND p.clave IS NULL AND UPPER(p.descripcion) = UPPER(v.modulo) AND p.activo
 WHERE NOT EXISTS (SELECT 1 FROM menu x WHERE x.clave = v.clave AND x.activo);

-- ventanas críticas de Seguridad y su módulo
UPDATE menu SET protegida = true, solo_admin = true WHERE clave IN ('menu', 'usuario', 'permiso') AND activo;
UPDATE menu SET protegida = true WHERE id_menu_padre IS NULL AND clave IS NULL AND UPPER(descripcion) = UPPER('Módulo Seguridad');

DO $$
BEGIN
    IF EXISTS (SELECT 1 FROM menu WHERE activo AND id_menu_padre IS NOT NULL AND ruta IS NULL) OR EXISTS (SELECT 1 FROM menu WHERE clave IS NOT NULL AND id_menu_padre IS NULL) THEN
        RAISE EXCEPTION 'Quedaron ventanas sin módulo o sin ruta: revise la tabla menu antes de seguir.';
    END IF;
    IF NOT EXISTS (SELECT 1 FROM pg_constraint WHERE conname = 'ck_menu_tipo' AND conrelid = 'public.menu'::regclass) THEN
        ALTER TABLE menu ADD CONSTRAINT ck_menu_tipo CHECK (
            (id_menu_padre IS NULL AND clave IS NULL AND ruta IS NULL) OR (id_menu_padre IS NOT NULL AND clave IS NOT NULL));
    END IF;
END $$;

CREATE OR REPLACE FUNCTION fn_menu_protegida() RETURNS trigger AS $f$
BEGIN
    IF TG_OP = 'DELETE' THEN
        IF OLD.protegida THEN
            RAISE EXCEPTION 'La entrada de menú "%" está protegida: no se puede borrar.', OLD.descripcion;
        END IF;
        RETURN OLD;
    END IF;
    IF OLD.protegida AND ((NEW.activo = false AND OLD.activo)
                          OR NEW.protegida IS DISTINCT FROM OLD.protegida
                          OR (NEW.solo_admin = false AND OLD.solo_admin)
                          OR NEW.clave IS DISTINCT FROM OLD.clave
                          OR NEW.id_menu_padre IS DISTINCT FROM OLD.id_menu_padre
                          OR NEW.ruta IS DISTINCT FROM OLD.ruta) THEN
        RAISE EXCEPTION 'La entrada de menú "%" está protegida: no se puede anular, mover ni quitarle la exclusividad del Administrador.', OLD.descripcion;
    END IF;
    RETURN NEW;
END;
$f$ LANGUAGE plpgsql;

CREATE TRIGGER trg_menu_protegida BEFORE UPDATE OR DELETE ON menu FOR EACH ROW EXECUTE FUNCTION fn_menu_protegida();

COMMIT;
